const seed=()=>({users:[{id:'u1',name:'Administrador General',email:'admin@agreserge.com',password:'1234',role:'Administrador del sistema'},{id:'u2',name:'Administrativo Documental',email:'documental@agreserge.com',password:'1234',role:'Administrativo AGRESERGE'},{id:'u3',name:'Carolina Rodríguez',email:'lider@agreserge.com',password:'1234',role:'Líder'},{id:'u4',name:'Agremiado Demo',email:'agremiado@agreserge.com',password:'1234',role:'Agremiado',type:'Asistencial',areaId:'a1',leaderId:'u3'}] as User[],institutions:[{id:'h1',name:'Hospital Gonzalo Contreras E.S.E',nit:'764000165501',city:'La Unión Valle'}] as Institution[],areas:[{id:'a1',name:'Urgencias',institutionId:'h1',leaderId:'u3'},{id:'a2',name:'Administrativa',institutionId:'h1'}] as Area[],contracts:[{id:'c1',institutionId:'h1',number:'002',year:'2026',month:'Enero',start:'2026-01-01',end:'2026-06-30',object:'Prestar apoyo y acompañamiento en la gestión para la prestación de servicios profesionales y técnicos en procesos asistenciales y administrativos.',value:'0'}] as Contract[],assignments:[] as Assignment[],documents:{} as Record<string,Doc[]>});
function useDB(){const[db,setDb]=useState<any>(null);useEffect(()=>{const raw=localStorage.getItem('agreserge_db_v5');setDb(raw?JSON.parse(raw):seed())},[]);const save=(n:any)=>{setDb(n);localStorage.setItem('agreserge_db_v5',JSON.stringify(n))};return{db,save}}
export default function Page(){const{db,save}=useDB();const[session,setSession]=useState<User|null>(null);const[mode,setMode]=useState<'login'|'register'>('login');const[nav,setNav]=useState('Inicio');const[form,setForm]=useState<any>({email:'admin@agreserge.com',password:'1234',role:'Agremiado',type:'Asistencial'});if(!db)return null;const login=()=>{const u=db.users.find((x:User)=>x.email===form.email&&x.password===form.password);if(u){setSession(u);setNav('Inicio')}else alert('Usuario o clave incorrecta. Prueba admin@agreserge.com / 1234')};const register=()=>{const u={id:uid(),name:form.name||'Nuevo usuario',email:form.email,password:form.password||'1234',role:form.role,type:form.type};save({...db,users:[...db.users,u]});setSession(u);setNav('Inicio')};if(!session)return <Login mode={mode} setMode={setMode} form={form} setForm={setForm} login={login} register={register}/>;return <Shell session={session} setSession={setSession} nav={nav} setNav={setNav} db={db} save={save}/>}
function Login(p:any){return <div className="loginPage"><div className="orb o1"/><div className="orb o2"/><section className="brandPanel"><div className="brandRow"><img className="logo" src="/logo.png"/><div><div className="kicker">Intranet AGRESERGE</div><h1>Acceso institucional moderno</h1></div></div><p>Acceso para agremiados, líderes y administrativos.</p></section><section className="loginCard"><span className="badge">AGRESERGE DEL VALLE</span><h2>{p.mode==='login'?'Inicio de sesión':'Registro de usuario'}</h2><p className="muted">Ingrese con su perfil autorizado para consultar sus módulos asignados.</p><div className="tabs"><button className={p.mode==='login'?'active':''} onClick={()=>p.setMode('login')}>Ingresar</button><button className={p.mode==='register'?'active':''} onClick={()=>p.setMode('register')}>Registrarse</button></div>{p.mode==='register'&&<div className="field"><label>Nombre completo</label><input className="input" onChange={e=>p.setForm({...p.form,name:e.target.value})}/></div>}<div className="field"><label>Correo electrónico</label><input className="input" value={p.form.email||''} onChange={e=>p.setForm({...p.form,email:e.target.value})}/></div><div className="field"><label>Contraseña</label><input className="input" type="password" value={p.form.password||''} onChange={e=>p.setForm({...p.form,password:e.target.value})}/></div>{p.mode==='register'&&<><div className="field"><label>Perfil</label><select value={p.form.role} onChange={e=>p.setForm({...p.form,role:e.target.value})}>{['Agremiado','Líder','Administrativo AGRESERGE'].map(x=><option key={x}>{x}</option>)}</select></div>{p.form.role==='Agremiado'&&<div className="field"><label>Tipo de personal</label><select onChange={e=>p.setForm({...p.form,type:e.target.value})}><option>Asistencial</option><option>Administrativo</option></select></div>}</>}<button className="btn primary" style={{width:'100%',marginTop:10}} onClick={p.mode==='login'?p.login:p.register}>{p.mode==='login'?'Ingresar a la intranet':'Crear solicitud de acceso'}</button><div className="divider"/><p className="mini">Demo: admin@agreserge.com, documental@agreserge.com, lider@agreserge.com, agremiado@agreserge.com / clave 1234</p></section></div>}
function Shell({session,setSession,nav,setNav,db,save}:any){const menus=session.role==='Administrador del sistema'?['Inicio','Parametrización','Informe de actividades','Documentos','Análisis IA','Cambio de clave']:session.role==='Administrativo AGRESERGE'?['Inicio','Informe de actividades','Documentos','Análisis IA','Cambio de clave']:session.role==='Líder'?['Inicio','Mis agremiados','Informe de actividades','Cambio de clave']:['Inicio','Ficha técnica','Cargue documental','Cambio de clave'];return <div className="app"><aside className="side"><div className="sideBrand"><img src="/logo.png"/><div><b>Intranet AGRESERGE</b><span>{session.role}</span></div></div><nav className="nav">{menus.map((m:string)=><button key={m} className={nav===m?'active':''} onClick={()=>setNav(m)}>{icon(m)}{m}</button>)}</nav><button className="btn ghost" onClick={()=>setSession(null)}><LogOut size={16}/> Salir</button></aside><main className="main"><div className="top"><div><span className="badge">{session.name}</span><h1>{nav}</h1></div><span className="badge">Base local funcional</span></div>{nav==='Inicio'&&<Home session={session} db={db}/>} {nav==='Parametrización'&&<Params db={db} save={save}/>} {nav==='Documentos'&&<Documents db={db} save={save}/>} {nav==='Ficha técnica'&&<Ficha session={session} db={db} save={save}/>} {nav==='Cargue documental'&&<UploadDocs session={session} db={db} save={save}/>} {nav==='Cambio de clave'&&<Password session={session} setSession={setSession} db={db} save={save}/>} {nav==='Mis agremiados'&&<MyPeople session={session} db={db}/>} {nav==='Informe de actividades'&&<ActivityReports session={session} db={db} save={save}/>} {nav==='Análisis IA'&&<AIAnalysis db={db}/>}</main></div>}
function icon(m:string){const map:any={'Parametrización':<FolderKanban size={18}/>,'Informe de actividades':<FileText size={18}/>,'Documentos':<ClipboardCheck size={18}/>,'Análisis IA':<Bot size={18}/>,'Cambio de clave':<KeyRound size={18}/>,'Mis agremiados':<Users size={18}/>,'Ficha técnica':<UserCheck size={18}/>,'Cargue documental':<ClipboardCheck size={18}/>};return map[m]||<BarChart3 size={18}/>}
function docMetrics(db:any,u:User){const list=u.type==='Administrativo'?adminDocs:assistDocs;const docs=db.documents[u.id]||[];const cargados=docs.filter((d:Doc)=>d.file).length;const aprobados=docs.filter((d:Doc)=>d.status==='Aprobado').length;const rechazados=docs.filter((d:Doc)=>d.status==='Rechazado').length;const revision=docs.filter((d:Doc)=>d.status==='En revisión'||d.file).length-aprobados-rechazados;const porcentaje=Math.round((aprobados/list.length)*100);const estado=aprobados===list.length?'Completo':rechazados>0?'Con observaciones':cargados>0?'En revisión':'Pendiente';return{total:list.length,cargados,aprobados,rechazados,revision:Math.max(0,revision),porcentaje,estado}}
function areaName(db:any,id?:string){return db.areas.find((a:Area)=>a.id===id)?.name||'Sin área'}
function instName(db:any,areaId?:string){const a=db.areas.find((x:Area)=>x.id===areaId);return db.institutions.find((i:Institution)=>i.id===a?.institutionId)?.name||'Sin institución'}
function Home({session,db}:any){const ag=db.users.filter((u:User)=>u.role==='Agremiado');const lideres=db.users.filter((u:User)=>u.role==='Líder');const docs=ag.map((u:User)=>docMetrics(db,u));const prom=ag.length?Math.round(docs.reduce((a:any,b:any)=>a+b.porcentaje,0)/ag.length):0;const completos=docs.filter((d:any)=>d.estado==='Completo').length;const observados=docs.filter((d:any)=>d.estado==='Con observaciones').length;return <div className="grid"><div className="card span12"><h3>Panel principal</h3><p className="muted">Sistema en español para gestión documental, parametrización institucional, seguimiento de informes y análisis ejecutivo.</p></div>{[['Instituciones',db.institutions.length,Building2],['Agremiados',ag.length,Users],['Líderes',lideres.length,UserCheck],['Informes asignados',db.assignments.length,FileText]].map(([t,n,I]:any)=><div className="card span3" key={t}><div className="module"><div className="icon"><I size={22}/></div><div><h3>{n}</h3><div className="muted">{t}</div></div></div></div>)}{(session.role==='Administrador del sistema'||session.role==='Administrativo AGRESERGE')&&<><div className="card span4"><h3>Cumplimiento documental</h3><div className="bigNumber">{prom}%</div><p className="muted">Promedio de documentos aprobados en agremiados activos.</p><div className="progress"><i style={{width:`${prom}%`}}/></div></div><div className="card span4"><h3>Estado general</h3><div className="statusGrid"><span className="pill ok">Completos: {completos}</span><span className="pill rev">En revisión: {docs.filter((d:any)=>d.estado==='En revisión').length}</span><span className="pill bad">Observados: {observados}</span><span className="pill pend">Pendientes: {docs.filter((d:any)=>d.estado==='Pendiente').length}</span></div></div><div className="card span4"><h3>Reportes rápidos</h3><p className="muted">Indicadores por hospital, área, líder, tipo de personal, mes, año e informe contractual.</p><button className="btn primary" onClick={()=>alert('Reporte ejecutivo generado en modo demo')}>Generar reporte ejecutivo</button></div><div className="card span12"><h3>Dashboard documental por institución</h3><table className="table"><thead><tr><th>Institución</th><th>Agremiados</th><th>Aprobados</th><th>Avance</th><th>Alertas</th></tr></thead><tbody>{db.institutions.map((i:Institution)=>{const areas=db.areas.filter((a:Area)=>a.institutionId===i.id).map((a:Area)=>a.id);const users=ag.filter((u:User)=>areas.includes(u.areaId||''));const m=users.map((u:User)=>docMetrics(db,u));const avance=users.length?Math.round(m.reduce((a:any,b:any)=>a+b.porcentaje,0)/users.length):0;return <tr key={i.id}><td>{i.name}</td><td>{users.length}</td><td>{m.filter((x:any)=>x.estado==='Completo').length}</td><td><div className="progress"><i style={{width:`${avance}%`}}/></div><span className="mini">{avance}%</span></td><td>{m.filter((x:any)=>x.rechazados>0).length} con observaciones</td></tr>})}</tbody></table></div></>}</div>}
function Params({db,save}:any){const[inst,setInst]=useState<any>({});const[area,setArea]=useState<any>({});const[user,setUser]=useState<any>({role:'Agremiado',type:'Asistencial'});const[contract,setContract]=useState<any>({year:'2026',month:'Enero'});const addInst=()=>{if(!inst.name)return;save({...db,institutions:[...db.institutions,{id:uid(),...inst}]});setInst({})};const addArea=()=>{if(!area.name)return;save({...db,areas:[...db.areas,{id:uid(),...area}]});setArea({})};const addUser=()=>{if(!user.name)return;save({...db,users:[...db.users,{id:uid(),email:user.email||`${uid()}@agreserge.com`,password:'1234',...user}]});setUser({role:'Agremiado',type:'Asistencial'})};const addContract=()=>{if(!contract.number)return;save({...db,contracts:[...db.contracts,{id:uid(),...contract}]});setContract({year:'2026',month:'Enero'})};return <div className="grid"><div className="card span12"><h3>Módulo de parametrización general</h3><p className="muted">Configure instituciones, contratos, áreas, líderes, agremiados y responsabilidades. Todo queda organizado para alimentar documentos, informes, análisis y dashboards.</p><div className="paramTabs"><span>1. Instituciones</span><span>2. Áreas</span><span>3. Usuarios</span><span>4. Contratos</span><span>5. Asignaciones</span></div></div><Crud title="Instituciones / hospitales" span="span6" data={inst} setData={setInst} fields={['name','nit','city']} action={addInst}/><Crud title="Áreas por institución" span="span6" data={area} setData={setArea} fields={['name']} action={addArea} extra={<><select onChange={e=>setArea({...area,institutionId:e.target.value})}><option>Seleccione institución</option>{db.institutions.map((i:Institution)=><option value={i.id} key={i.id}>{i.name}</option>)}</select><select onChange={e=>setArea({...area,leaderId:e.target.value})}><option>Líder responsable del área</option>{db.users.filter((u:User)=>u.role==='Líder').map((u:User)=><option value={u.id} key={u.id}>{u.name}</option>)}</select></>}/><Crud title="Usuarios, roles y asignaciones" span="span6" data={user} setData={setUser} fields={['name','email']} action={addUser} extra={<><select value={user.role} onChange={e=>setUser({...user,role:e.target.value})}>{['Agremiado','Líder','Administrativo AGRESERGE','Administrador del sistema'].map(x=><option key={x}>{x}</option>)}</select>{user.role==='Agremiado'&&<><select onChange={e=>setUser({...user,type:e.target.value})}><option>Asistencial</option><option>Administrativo</option></select><select onChange={e=>setUser({...user,areaId:e.target.value})}><option>Área asignada</option>{db.areas.map((a:Area)=><option value={a.id} key={a.id}>{a.name} - {instName(db,a.id)}</option>)}</select><select onChange={e=>setUser({...user,leaderId:e.target.value})}><option>Líder asignado</option>{db.users.filter((u:User)=>u.role==='Líder').map((u:User)=><option value={u.id} key={u.id}>{u.name}</option>)}</select></>}</>}/><Crud title="Contratos por institución" span="span6" data={contract} setData={setContract} fields={['number','year','month','start','end','value']} action={addContract} extra={<><select onChange={e=>setContract({...contract,institutionId:e.target.value})}><option>Institución contratante</option>{db.institutions.map((i:Institution)=><option value={i.id} key={i.id}>{i.name}</option>)}</select><textarea placeholder="Objeto contractual" onChange={e=>setContract({...contract,object:e.target.value})}/></>}/><Listings db={db} save={save}/></div>}
function Crud({title,span,data,setData,fields,action,extra}:any){return <div className={`card ${span}`}><h3>{title}</h3>{fields.map((f:string)=><div className="field" key={f}><label>{f}</label><input className="input" value={data[f]||''} onChange={e=>setData({...data,[f]:e.target.value})}/></div>)}{extra}<button className="btn primary" onClick={action}><Plus size={16}/> Guardar</button></div>}
function Listings({db,save}:any){const del=(col:string,id:string)=>save({...db,[col]:db[col].filter((x:any)=>x.id!==id)});return <div className="card span12"><h3>Registros guardados</h3><table className="table"><tbody>{['institutions','areas','users','contracts'].map(col=><tr key={col}><td><b>{col}</b></td><td>{db[col].length} registros</td><td><button className="btn ghost" onClick={()=>alert(JSON.stringify(db[col],null,2))}>Ver detalle</button></td></tr>)}</tbody></table></div>}
function Ficha({session,db,save}:any){const[f,setF]=useState<any>(session);const guardar=()=>{const users=db.users.map((u:User)=>u.id===session.id?{...u,...f}:u);save({...db,users});alert('Ficha técnica guardada')};return <div className="card"><h3>Ficha técnica de registro</h3><div className="grid"><div className="span6 field"><label>Nombre</label><input className="input" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></div><div className="span6 field"><label>Correo</label><input className="input" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></div><div className="span6 field"><label>Tipo de personal</label><select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option>Asistencial</option><option>Administrativo</option></select></div><div className="span6 field"><label>Teléfono</label><input className="input" onChange={e=>setF({...f,phone:e.target.value})}/></div></div><button className="btn primary" onClick={guardar}>Guardar ficha técnica</button></div>}
function UploadDocs({session,db,save}:any){const list=session.type==='Administrativo'?adminDocs:assistDocs;const docs=db.documents[session.id]||list.map(name=>({name,status:'Pendiente',comment:'Sin cargar'}));const setDocs=(d:Doc[])=>save({...db,documents:{...db.documents,[session.id]:d}});const done=docs.filter((d:Doc)=>d.file).length;return <div className="card"><h3>Proceso de vinculación documental</h3><p className="muted">Cargue, reemplace, elimine y consulte sus documentos. Avance: {done}/{docs.length}</p><div className="progress"><i style={{width:`${done/docs.length*100}%`}}/></div>{docs.map((d:Doc,i:number)=><div className="docItem" key={d.name}><b>{i+1}. {d.name}</b><span className={`pill ${d.file?'rev':'pend'}`}>{d.file?'En revisión':'Pendiente'}</span><input type="date" className="input" onChange={e=>{const n=[...docs];n[i].expires=e.target.value;setDocs(n)}}/><div className="row"><input type="file" onChange={e=>{const n=[...docs];n[i]={...n[i],file:e.target.files?.[0]?.name,status:'En revisión',comment:'Documento cargado para revisión'};setDocs(n)}}/><button className="btn danger" onClick={()=>{const n=[...docs];n[i]={name:d.name,status:'Pendiente',comment:'Sin cargar'};setDocs(n)}}><Trash2 size={14}/></button></div></div>)}</div>}
function Documents({db,save}:any){const ag=db.users.filter((u:User)=>u.role==='Agremiado');const[f,setF]=useState<any>({q:'',institution:'',area:'',leader:'',type:'',status:''});const filtered=ag.filter((u:User)=>{const m=docMetrics(db,u);const area=db.areas.find((a:Area)=>a.id===u.areaId);return(!f.q||u.name.toLowerCase().includes(f.q.toLowerCase())||u.email.toLowerCase().includes(f.q.toLowerCase()))&&(!f.institution||area?.institutionId===f.institution)&&(!f.area||u.areaId===f.area)&&(!f.leader||u.leaderId===f.leader)&&(!f.type||u.type===f.type)&&(!f.status||m.estado===f.status)});const[sel,setSel]=useState<User|null>(filtered[0]||ag[0]||null);const totals=filtered.map((u:User)=>docMetrics(db,u));return <div className="grid"><div className="card span12"><h3>Revisión documental de agremiados</h3><p className="muted">Filtros para revisar bases grandes por institución, área, líder, tipo de personal, estado documental y búsqueda general.</p><div className="filterGrid"><input className="input" placeholder="Buscar por nombre o correo" value={f.q} onChange={e=>setF({...f,q:e.target.value})}/><select value={f.institution} onChange={e=>setF({...f,institution:e.target.value,area:''})}><option value="">Todas las instituciones</option>{db.institutions.map((i:Institution)=><option value={i.id} key={i.id}>{i.name}</option>)}</select><select value={f.area} onChange={e=>setF({...f,area:e.target.value})}><option value="">Todas las áreas</option>{db.areas.filter((a:Area)=>!f.institution||a.institutionId===f.institution).map((a:Area)=><option value={a.id} key={a.id}>{a.name}</option>)}</select><select value={f.leader} onChange={e=>setF({...f,leader:e.target.value})}><option value="">Todos los líderes</option>{db.users.filter((u:User)=>u.role==='Líder').map((u:User)=><option value={u.id} key={u.id}>{u.name}</option>)}</select><select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option value="">Todo el personal</option><option>Asistencial</option><option>Administrativo</option></select><select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="">Todos los estados</option><option>Pendiente</option><option>En revisión</option><option>Con observaciones</option><option>Completo</option></select></div><div className="kpiRow"><span className="pill pend">Filtrados: {filtered.length}</span><span className="pill ok">Completos: {totals.filter((x:any)=>x.estado==='Completo').length}</span><span className="pill rev">En revisión: {totals.filter((x:any)=>x.estado==='En revisión').length}</span><span className="pill bad">Con observaciones: {totals.filter((x:any)=>x.estado==='Con observaciones').length}</span></div></div><div className="card span5"><h3>Agremiados encontrados</h3><table className="table"><thead><tr><th>Agremiado</th><th>Entidad / área</th><th>Avance</th></tr></thead><tbody>{filtered.map((u:User)=>{const m=docMetrics(db,u);return <tr key={u.id} onClick={()=>setSel(u)} style={{cursor:'pointer'}}><td><b>{u.name}</b><br/><span className="mini">{u.type} · {db.users.find((l:User)=>l.id===u.leaderId)?.name||'Sin líder'}</span></td><td>{instName(db,u.areaId)}<br/><span className="mini">{areaName(db,u.areaId)}</span></td><td><span className={`pill ${m.estado==='Completo'?'ok':m.estado==='Con observaciones'?'bad':m.estado==='En revisión'?'rev':'pend'}`}>{m.estado}</span><div className="progress small"><i style={{width:`${m.porcentaje}%`}}/></div></td></tr>})}</tbody></table></div><div className="card span7"><h3>Detalle y previsualización</h3>{sel?<><div className="personHeader"><div><b>{sel.name}</b><p className="muted">{instName(db,sel.areaId)} · {areaName(db,sel.areaId)} · Líder: {db.users.find((l:User)=>l.id===sel.leaderId)?.name||'Sin líder'}</p></div><span className="badge">{docMetrics(db,sel).porcentaje}% aprobado</span></div><ReviewUser user={sel} db={db} save={save}/></>:<p className="muted">Seleccione un agremiado para revisar documentos.</p>}</div></div>}
function ReviewUser({user,db,save}:any){const list=user.type==='Administrativo'?adminDocs:assistDocs;const docs=db.documents[user.id]||list.map((name:string)=>({name,status:'Pendiente',comment:'Sin cargar'}));const setDocs=(d:Doc[])=>save({...db,documents:{...db.documents,[user.id]:d}});return <>{docs.map((d:Doc,i:number)=><div className="docItem" key={d.name}><b>{d.name}</b><span className={`pill ${d.status==='Aprobado'?'ok':d.status==='Rechazado'?'bad':d.file?'rev':'pend'}`}>{d.status}</span><span className="mini">{d.file||'Sin archivo'} {d.expires?' vence '+d.expires:''}</span><div className="row"><button className="btn ghost" onClick={()=>alert('Vista previa demo: '+(d.file||'Sin archivo'))}><Eye size={14}/> Vista previa</button><button className="btn" onClick={()=>{const n=[...docs];n[i].status='Aprobado';n[i].comment='Validado correctamente';setDocs(n)}}>Aprobar</button><button className="btn danger" onClick={()=>{const n=[...docs];n[i].status='Rechazado';n[i].comment='Revisar legibilidad o vigencia';setDocs(n)}}>Rechazar</button></div></div>)}</>}
function AIAnalysis({db}:any){const ag=db.users.filter((u:User)=>u.role==='Agremiado');return <div className="grid">{ag.map((u:User)=>{const docs=db.documents[u.id]||[];const total=(u.type==='Administrativo'?adminDocs:assistDocs).length;const carg=docs.filter((d:Doc)=>d.file).length;const apr=docs.filter((d:Doc)=>d.status==='Aprobado').length;return <div className="card span6" key={u.id}><div className="row"><div className="icon"><Bot/></div><div><h3>{u.name}</h3><p className="muted">Diagnóstico IA documental</p></div></div><p>La IA detecta {carg} documentos cargados de {total}. Aprobados: {apr}. Pendientes aproximados: {total-carg}. Recomendación: verificar legibilidad, vigencia y coherencia entre cédula, RETHUS/RUT, afiliaciones y certificaciones.</p><button className="btn primary" onClick={()=>alert('Informe IA generado para '+u.name)}>Generar informe IA</button></div>})}</div>}
function Password({session,setSession,db,save}:any){const[p,setP]=useState('');return <div className="card"><h3>Cambio de clave</h3><div className="field"><label>Nueva contraseña</label><input className="input" type="password" onChange={e=>setP(e.target.value)}/></div><button className="btn primary" onClick={()=>{const users=db.users.map((u:User)=>u.id===session.id?{...u,password:p}:u);save({...db,users});setSession({...session,password:p});alert('Clave actualizada')}}>Actualizar clave</button></div>}
function MyPeople({session,db}:any){const people=db.users.filter((u:User)=>u.leaderId===session.id);return <div className="card"><h3>Agremiados asignados</h3><table className="table"><thead><tr><th>Nombre</th><th>Tipo</th><th>Área</th><th>Estado documental</th></tr></thead><tbody>{people.map((u:User)=><tr key={u.id}><td>{u.name}</td><td>{u.type}</td><td>{db.areas.find((a:Area)=>a.id===u.areaId)?.name||'Sin área'}</td><td><span className="pill rev">En seguimiento</span></td></tr>)}</tbody></table></div>}
function ActivityReports({session,db,save}:any){const isLeader=session.role==='Líder';const[contract,setContract]=useState(db.contracts[0]?.id||'');const[assign,setAssign]=useState<any>({year:'2026',month:'Enero'});const[preview,setPreview]=useState(false);const add=()=>{save({...db,assignments:[...db.assignments,{id:uid(),contractId:contract,status:'Asignado',comments:'Pendiente por desarrollar',...assign}]});setAssign({year:'2026',month:'Enero'})};const visible=isLeader?db.assignments.filter((a:Assignment)=>a.leaderId===session.id):db.assignments;return <div className="grid">{!isLeader&&<div className="card span12"><h3>Crear y asignar informe de actividades</h3><div className="grid"><div className="span4 field"><label>Contrato / institución</label><select value={contract} onChange={e=>setContract(e.target.value)}>{db.contracts.map((c:Contract)=><option value={c.id} key={c.id}>Contrato {c.number} - {db.institutions.find((i:Institution)=>i.id===c.institutionId)?.name}</option>)}</select></div><div className="span4 field"><label>Anexo / punto</label><select onChange={e=>{const [n,t]=(e.target.value).split('|');setAssign({...assign,annex:+n,title:t,obligation:t})}}><option>Seleccione anexo</option>{annexes.map((a:any)=><option value={a[0]+'|'+a[1]} key={a[0]}>Anexo {a[0]} - {a[1]}</option>)}</select></div><div className="span4 field"><label>Líder responsable</label><select onChange={e=>setAssign({...assign,leaderId:e.target.value})}><option>Seleccione líder</option>{db.users.filter((u:User)=>u.role==='Líder').map((u:User)=><option value={u.id} key={u.id}>{u.name}</option>)}</select></div><div className="span4 field"><label>Año</label><input className="input" value={assign.year} onChange={e=>setAssign({...assign,year:e.target.value})}/></div><div className="span4 field"><label>Mes</label><input className="input" value={assign.month} onChange={e=>setAssign({...assign,month:e.target.value})}/></div><div className="span4 field"><label>Link documento Google</label><input className="input" placeholder="https://docs.google.com/..." onChange={e=>setAssign({...assign,googleUrl:e.target.value})}/></div></div><button className="btn primary" onClick={add}>Asignar responsabilidad</button></div>}<div className="card span12"><h3>{isLeader?'Mis responsabilidades de informe':'Seguimiento de informes asignados'}</h3><table className="table"><thead><tr><th>Anexo</th><th>Responsable</th><th>Periodo</th><th>Documento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{visible.map((a:Assignment)=><tr key={a.id}><td>Anexo {a.annex}. {a.title}</td><td>{db.users.find((u:User)=>u.id===a.leaderId)?.name}</td><td>{a.month} {a.year}</td><td>{a.googleUrl?<a className="link" href={a.googleUrl} target="_blank"><LinkIcon size={14}/> Abrir Google Docs</a>:'Sin link'}</td><td><span className="pill rev">{a.status}</span></td><td><button className="btn ghost" onClick={()=>alert('Previsualización del anexo '+a.annex)}><Eye size={14}/> Previsualizar</button></td></tr>)}</tbody></table></div>{!isLeader&&<div className="card span12"><h3>Generar informe consolidado</h3><p className="muted">Consolida los anexos asignados por hospital, contrato, mes y año. El informe final puede enlazarse a Google Docs para edición y entrega al hospital.</p><button className="btn primary" onClick={()=>setPreview(true)}><FileText size={16}/> Generar informe de actividades</button></div>}{preview&&<div className="modal"><div className="modalBox"><h2>Informe de actividades consolidado</h2><p><b>Tipo:</b> Informe parcial / final</p><p><b>Contratante:</b> {db.institutions.find((i:Institution)=>i.id===db.contracts.find((c:Contract)=>c.id===contract)?.institutionId)?.name}</p><p><b>Periodo:</b> {assign.month||'Enero'} {assign.year||'2026'}</p><table className="table"><tbody>{visible.map((a:Assignment)=><tr key={a.id}><td>Anexo {a.annex}</td><td>{a.title}</td><td>{db.users.find((u:User)=>u.id===a.leaderId)?.name}</td></tr>)}</tbody></table><button className="btn primary" onClick={()=>alert('Informe consolidado generado en modo demo. En producción se conecta con Google Docs API.')}>Guardar informe final</button> <button className="btn ghost" onClick={()=>setPreview(false)}>Cerrar</button></div></div>}</div>}
